            return "cannot be travelled";
        }
    }

    // Check if the starting n-tersection is the same as the ending n-tersection
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Check if the starting n-tersection is adjacent to the ending n-tersection
    for (int[] path : paths) {
        if (path[0] == start[0] && path[1] == start[1]) {
            return "can be travelled";
        }
    }

    // Check if the ending n-tersection is adjacent to the starting n-tersection
