public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (s.length() > 0) {
        // Step 1: Pick the smallest character from s and append it to the result
        char smallest = s.charAt(0);
        result.append(smallest);
        s = s.substring(1);

        // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it
        int smallestIndex = s.indexOf(smallest);
        while (smallestIndex < s.length() - 1 && s.charAt(smallestIndex + 1) <= smallest) {
            smallestIndex++;
        }
        if (smallestIndex < s.length()) {
            result.append(s.charAt(smallestIndex));
            s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
        }

        // Step 3: Repeat step 2 until you cannot pick more characters
        while (s.length() > 0) {
            // Step 4: Pick the largest character from s and append it to the result
            char largest = s.charAt(s.length() - 1);
            result.append(largest);
            s = s.substring(0, s.length() - 1);

            // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it
            int largestIndex = s.lastIndexOf(largest);
            while (largestIndex > 0 && s.charAt(largestIndex - 1) >= largest) {
                largestIndex--;
            }
            if (largestIndex > 0) {
                result.append(s.charAt(largestIndex - 1));
                s = s.substring(0, largestIndex) + s.substring(largestIndex);
            }
        }
    }
    return result.toString();
}

