public int kthFactor(int n, int k) {
    if (k > factorCount(n)) {
        return -1;
    }
    int factor = 1;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            if (factor == k) {
                return i;
            }
            factor++;
        }
    }
    return -1;
}

private int factorCount(int n) {
