public static int calculateEnergy(String s) {
    int maxLength = 0;
    int currentLength = 0;
    char currentChar = ' ';

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            currentLength++;
        } else {
            if (currentLength > maxLength) {
                maxLength = currentLength;
            }
            currentLength = 1;
            currentChar = c;
        }
    }

    if (currentLength > maxLength) {
        maxLength = currentLength;
    }

    return maxLength;
}
